/** Saves a PDF response as a file (name from Content-Disposition). */
export function savePdfBlob(blob: Blob, contentDisposition: string | undefined, fallbackName: string): void {
  const match = /filename="?([^";]+)"?/i.exec(contentDisposition ?? "");
  const url = URL.createObjectURL(new Blob([blob], { type: "application/pdf" }));
  const link = document.createElement("a");
  link.href = url;
  link.download = match?.[1] ?? fallbackName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 10_000);
}

/** The official PDF certificate — generated by the backend from the
 * attempt's stored result (nothing is sent from here except the id). */
export async function downloadVizuMultilevelCertificatePdf(attemptId: string): Promise<void> {
  const response = await api.get<Blob>(`${BASE}/${attemptId}/certificate/pdf`, { responseType: "blob" });
  savePdfBlob(response.data, response.headers["content-disposition"] as string | undefined, "VIZU-Zertifikat.pdf");
}

